DECLARE @B bigint=(SELECT BatchId FROM ssis_flow.Context),@Previous bigint=(SELECT PreviousVersion FROM ssis_flow.Context),@Next bigint=(SELECT NextVersion FROM ssis_flow.Context);
IF @Previous IS NULL BEGIN
INSERT etl_raw.[WorkOrderRouting]([WorkOrderID],[ProductID],[OperationSequence],[LocationID],[ScheduledStartDate],[ScheduledEndDate],[ActualStartDate],[ActualEndDate],[ActualResourceHrs],[PlannedCost],[ActualCost],[ModifiedDate],LoadBatchID) SELECT S.[WorkOrderID],S.[ProductID],S.[OperationSequence],S.[LocationID],S.[ScheduledStartDate],S.[ScheduledEndDate],S.[ActualStartDate],S.[ActualEndDate],S.[ActualResourceHrs],S.[PlannedCost],S.[ActualCost],S.[ModifiedDate],@B FROM ssis_flow.Delta_WorkOrderRouting S;
INSERT stg.[WorkOrderRouting]([WorkOrderID],[ProductID],[OperationSequence],[LocationID],[ScheduledStartDate],[ScheduledEndDate],[ActualStartDate],[ActualEndDate],[ActualResourceHrs],[PlannedCost],[ActualCost],[ModifiedDate],LoadBatchID) SELECT [WorkOrderID],[ProductID],[OperationSequence],[LocationID],[ScheduledStartDate],[ScheduledEndDate],[ActualStartDate],[ActualEndDate],[ActualResourceHrs],[PlannedCost],[ActualCost],[ModifiedDate],@B FROM etl_raw.[WorkOrderRouting];
INSERT etl_v2.SourceChange SELECT @B,N'Production.WorkOrderRouting','I',@Next,(SELECT R.[WorkOrderID],R.[ProductID],R.[OperationSequence] FOR JSON PATH,WITHOUT_ARRAY_WRAPPER),NULL FROM etl_raw.[WorkOrderRouting] R;
END ELSE BEGIN
SELECT [WorkOrderID],[ProductID],[OperationSequence],CONVERT(char(1),FlowOperation) SYS_CHANGE_OPERATION,FlowVersion SYS_CHANGE_VERSION INTO #CT_WorkOrderRouting FROM ssis_flow.Delta_WorkOrderRouting;
INSERT etl_v2.SourceChange SELECT @B,N'Production.WorkOrderRouting',C.SYS_CHANGE_OPERATION,C.SYS_CHANGE_VERSION,(SELECT C.[WorkOrderID],C.[ProductID],C.[OperationSequence] FOR JSON PATH,WITHOUT_ARRAY_WRAPPER),(SELECT R.* FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES) FROM #CT_WorkOrderRouting C LEFT JOIN etl_raw.[WorkOrderRouting] R ON R.[WorkOrderID]=C.[WorkOrderID] AND R.[ProductID]=C.[ProductID] AND R.[OperationSequence]=C.[OperationSequence];
DELETE R FROM etl_raw.[WorkOrderRouting] R JOIN #CT_WorkOrderRouting C ON R.[WorkOrderID]=C.[WorkOrderID] AND R.[ProductID]=C.[ProductID] AND R.[OperationSequence]=C.[OperationSequence] WHERE C.SYS_CHANGE_OPERATION='D';
UPDATE R SET R.[LocationID]=S.[LocationID],R.[ScheduledStartDate]=S.[ScheduledStartDate],R.[ScheduledEndDate]=S.[ScheduledEndDate],R.[ActualStartDate]=S.[ActualStartDate],R.[ActualEndDate]=S.[ActualEndDate],R.[ActualResourceHrs]=S.[ActualResourceHrs],R.[PlannedCost]=S.[PlannedCost],R.[ActualCost]=S.[ActualCost],R.[ModifiedDate]=S.[ModifiedDate],R.LoadBatchID=@B FROM etl_raw.[WorkOrderRouting] R JOIN #CT_WorkOrderRouting C ON R.[WorkOrderID]=C.[WorkOrderID] AND R.[ProductID]=C.[ProductID] AND R.[OperationSequence]=C.[OperationSequence] JOIN ssis_flow.Delta_WorkOrderRouting S ON S.[WorkOrderID]=C.[WorkOrderID] AND S.[ProductID]=C.[ProductID] AND S.[OperationSequence]=C.[OperationSequence] WHERE C.SYS_CHANGE_OPERATION<>'D';
INSERT etl_raw.[WorkOrderRouting]([WorkOrderID],[ProductID],[OperationSequence],[LocationID],[ScheduledStartDate],[ScheduledEndDate],[ActualStartDate],[ActualEndDate],[ActualResourceHrs],[PlannedCost],[ActualCost],[ModifiedDate],LoadBatchID) SELECT S.[WorkOrderID],S.[ProductID],S.[OperationSequence],S.[LocationID],S.[ScheduledStartDate],S.[ScheduledEndDate],S.[ActualStartDate],S.[ActualEndDate],S.[ActualResourceHrs],S.[PlannedCost],S.[ActualCost],S.[ModifiedDate],@B FROM #CT_WorkOrderRouting C JOIN ssis_flow.Delta_WorkOrderRouting S ON S.[WorkOrderID]=C.[WorkOrderID] AND S.[ProductID]=C.[ProductID] AND S.[OperationSequence]=C.[OperationSequence] WHERE C.SYS_CHANGE_OPERATION<>'D' AND NOT EXISTS(SELECT 1 FROM etl_raw.[WorkOrderRouting] R WHERE R.[WorkOrderID]=S.[WorkOrderID] AND R.[ProductID]=S.[ProductID] AND R.[OperationSequence]=S.[OperationSequence]);
INSERT stg.[WorkOrderRouting]([WorkOrderID],[ProductID],[OperationSequence],[LocationID],[ScheduledStartDate],[ScheduledEndDate],[ActualStartDate],[ActualEndDate],[ActualResourceHrs],[PlannedCost],[ActualCost],[ModifiedDate],LoadBatchID) SELECT R.[WorkOrderID],R.[ProductID],R.[OperationSequence],R.[LocationID],R.[ScheduledStartDate],R.[ScheduledEndDate],R.[ActualStartDate],R.[ActualEndDate],R.[ActualResourceHrs],R.[PlannedCost],R.[ActualCost],R.[ModifiedDate],@B FROM etl_raw.[WorkOrderRouting] R JOIN #CT_WorkOrderRouting C ON R.[WorkOrderID]=C.[WorkOrderID] AND R.[ProductID]=C.[ProductID] AND R.[OperationSequence]=C.[OperationSequence] WHERE C.SYS_CHANGE_OPERATION<>'D';
END;